// ══════════════════════════════════════════════════════════════════════════════
// GOOGLE DRIVE API HELPERS
// ══════════════════════════════════════════════════════════════════════════════

async function ensureDriveFolder(token, folderName, parentFolderId = null) {
  // Check if folder exists
  const searchQuery = parentFolderId 
    ? `name='${folderName}' and '${parentFolderId}' in parents and mimeType='application/vnd.google-apps.folder' and trashed=false`
    : `name='${folderName}' and mimeType='application/vnd.google-apps.folder' and trashed=false`;
  
  const searchRes = await fetch(
    `https://www.googleapis.com/drive/v3/files?q=${encodeURIComponent(searchQuery)}&fields=files(id,name)`,
    { headers: { Authorization: `Bearer ${token}` } }
  );
  const searchData = await searchRes.json();
  
  if (searchData.files && searchData.files.length > 0) {
    return searchData.files[0].id;
  }
  
  // Create folder
  const metadata = {
    name: folderName,
    mimeType: 'application/vnd.google-apps.folder',
    ...(parentFolderId && { parents: [parentFolderId] })
  };
  
  const createRes = await fetch('https://www.googleapis.com/drive/v3/files', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(metadata)
  });
  
  const createData = await createRes.json();
  return createData.id;
}

async function uploadFileToDrive(token, file, fileName, parentFolderId) {
  const metadata = {
    name: fileName,
    parents: [parentFolderId]
  };
  
  const formData = new FormData();
  formData.append('metadata', new Blob([JSON.stringify(metadata)], { type: 'application/json' }));
  formData.append('file', file);
  
  const response = await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id,name,mimeType,size,webViewLink,webContentLink', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${token}`
    },
    body: formData
  });
  
  return await response.json();
}

async function deleteFileFromDrive(token, fileId) {
  await fetch(`https://www.googleapis.com/drive/v3/files/${fileId}`, {
    method: 'DELETE',
    headers: {
      Authorization: `Bearer ${token}`
    }
  });
}

// ── Force Light Mode CSS Variables ──────────────────────────────────────────
const LIGHT_MODE_STYLE = `
  :root, [data-theme], * {
    color-scheme: light !important;
  }
  :root {
    --color-background-primary: #ffffff;
    --color-background-secondary: #f5f5f5;
    --color-background-tertiary: #f0f0f0;
    --color-text-primary: #111111;
    --color-text-secondary: #6b7280;
    --color-border-primary: #d1d5db;
    --color-border-secondary: #e5e7eb;
    --color-border-tertiary: #e5e7eb;
  }
  input, select, textarea {
    background: #ffffff !important;
    color: #111111 !important;
    border: 1px solid #d1d5db !important;
    border-radius: 6px;
    padding: 6px 10px;
  }
  html, body { overflow-x: hidden; }
  * { box-sizing: border-box; }
  @media (max-width: 767px) {
    /* Prevent any element from causing horizontal scroll */
    main, .main-content { max-width: 100vw; overflow-x: hidden; }
    /* Tables scroll inside their container */
    table { display: block; overflow-x: auto; -webkit-overflow-scrolling: touch; }
    /* Inputs always fit */
    input[type="time"], input[type="date"] { min-width: 0; width: 100% !important; }
    /* Mobile holdings stats grid: 2 cols instead of 4 */
    .mobile-stats-2col { grid-template-columns: 1fr 1fr !important; }
    /* Make pie chart wrap on mobile */
    .pie-wrap { flex-direction: column !important; align-items: center !important; }
    /* Bar charts: don't overflow */
    svg { max-width: 100%; }
  }
`;

// ── localStorage → kept only for one-time migration on first sign-in ──────────
const STORAGE_KEY = "fintrack_data_v2";

function migrateLocalStorage() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    localStorage.removeItem(STORAGE_KEY); // clear after migration
    return { ...defaultData, ...parsed };
  } catch (e) { return null; }
}


